/**
 * @summary Delete a campaign
 */
export const getDeleteCampaignUrl = (id: number) => {
  return `/api/spark/campaigns/${id}`;
};

export const deleteCampaign = async (
  id: number,
  options?: RequestInit,
): Promise<DeleteResponse> => {
  return customFetch<DeleteResponse>(getDeleteCampaignUrl(id), {
    ...options,
    method: "DELETE",
  });
};

export const getDeleteCampaignMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof deleteCampaign>>,
    TError,
    { id: number },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof deleteCampaign>>,
  TError,
  { id: number },
  TContext
> => {
  const mutationKey = ["deleteCampaign"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof deleteCampaign>>,
    { id: number }
  > = (props) => {
    const { id } = props ?? {};

    return deleteCampaign(id, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type DeleteCampaignMutationResult = NonNullable<
  Awaited<ReturnType<typeof deleteCampaign>>
>;

export type DeleteCampaignMutationError = ErrorType<unknown>;

/**
 * @summary Delete a campaign
 */
export const useDeleteCampaign = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof deleteCampaign>>,
    TError,
    { id: number },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof deleteCampaign>>,
  TError,
  { id: number },
  TContext
> => {
  return useMutation(getDeleteCampaignMutationOptions(options));
};

/**
 * @summary Run a SPARK command
 */
export const getRunCommandUrl = () => {
  return `/api/spark/command`;
};

export const runCommand = async (
  commandBody: CommandBody,
  options?: RequestInit,
): Promise<CommandResponse> => {
  return customFetch<CommandResponse>(getRunCommandUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(commandBody),
  });
};

export const getRunCommandMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof runCommand>>,
    TError,
    { data: BodyType<CommandBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof runCommand>>,
  TError,
  { data: BodyType<CommandBody> },
  TContext
> => {
  const mutationKey = ["runCommand"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof runCommand>>,
    { data: BodyType<CommandBody> }
  > = (props) => {
    const { data } = props ?? {};

    return runCommand(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type RunCommandMutationResult = NonNullable<
  Awaited<ReturnType<typeof runCommand>>
>;
export type RunCommandMutationBody = BodyType<CommandBody>;
export type RunCommandMutationError = ErrorType<unknown>;

/**
 * @summary Run a SPARK command
 */
export const useRunCommand = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof runCommand>>,
    TError,
    { data: BodyType<CommandBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof runCommand>>,
  TError,
  { data: BodyType<CommandBody> },
  TContext
> => {
  return useMutation(getRunCommandMutationOptions(options));
};
